import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchIncidentDetectionById,
  createIncidentDetection,
  updateIncidentDetection,
  routeIncidentDetection,
  claimIncidentDetection,
  reassignIncidentDetection,
  rejectIncidentDetection,
  cancelIncidentDetection,
  convertIncidentDetection,
  setSelectedDetection,
} from '../../store/slices/incidentDetectionsSlice';
import { addToast } from '../../store/slices/uiSlice';
import {
  IncidentDetection,
  IncidentDetectionStatus,
  createEmptyIncidentDetection,
} from '../../models/IncidentDetection';
import { useFormOptions } from '../../hooks/useFormOptions';
import { useIncidentDetectionPermissions } from '../../hooks/useIncidentDetectionPermissions';
import { utcToLocalInputValue, localInputToISOWithOffset } from '../../utils/dateTime';
import { getApiErrorMessage } from '../../utils/apiMessages';
import { filesEndpoint } from '../../services/files/endpoint';
import { SCYK_DETECTION_ENTITY_TYPE, scykDetectionImageUploadLabels } from '../../config/scykDetectionImageUpload';
import type { MedicalIncidentAttachment } from '../../models/MedicalIncident';
import {
  DetectionPhotosSection,
  attachmentsToUploadItems,
  resolveUploadDisplayName,
  type DetectionUploadItem,
} from './components/DetectionPhotosSection';
import styles from './IncidentDetectionFormPage.module.css';
import {
  ValidationErrors,
  ValidationRule,
  runValidation,
  scrollToFirstErrorSection,
  clearFieldErrors,
} from '../../utils/formValidation';
import { Button, Select } from '@linm-soft-org/linm-web-common-components';
import { IncidentLocationSearchInput } from '../../components/search/IncidentLocationSearchInput';

const IncidentDetectionFormPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const appNavigate = useAppNavigate();
  const dispatch = useAppDispatch();
  const isNew = !id || id === 'new';

  const { selected, saving, loading } = useAppSelector((s) => s.incidentDetections);
  const authUser = useAppSelector((s) => s.auth.user);
  const {
    departmentOptions,
    detectionLabel: L,
    detectionStatusOptions,
  } = useFormOptions('create-detection');

  const [form, setForm] = useState<Partial<IncidentDetection>>(createEmptyIncidentDetection);
  const [photos, setPhotos] = useState<DetectionUploadItem[]>([]);
  const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});
  const [rejectOpen, setRejectOpen] = useState(false);
  const [rejectReason, setRejectReason] = useState('');
  const [reassignOpen, setReassignOpen] = useState(false);
  const [reassignDeptId, setReassignDeptId] = useState('');

  const status = form.status ?? IncidentDetectionStatus.Draft;
  const isOwner = !!authUser?.id && form.detectorUserId === authUser.id;
  const perms = useIncidentDetectionPermissions();
  const sameTargetDept = !!authUser?.departmentId && form.targetDepartmentId === authUser.departmentId;
  const isClaimer = !!authUser?.id && form.claimedById === authUser.id;
  const canInboxAct = perms.isFullAccess || sameTargetDept || isClaimer;
  const canEdit = (isNew && perms.canCreate) || (status === IncidentDetectionStatus.Draft && isOwner && perms.canCreate);
  const canShowConvert = !isNew && perms.canConvert
    && (status === IncidentDetectionStatus.Routed || status === IncidentDetectionStatus.Claimed);
  const statusLabel = detectionStatusOptions.find((o) => o.value === status)?.label ?? status;

  useEffect(() => {
    const t = setTimeout(() => {
      if (!isNew && id) dispatch(fetchIncidentDetectionById(id));
      else dispatch(setSelectedDetection(null));
    }, 0);
    return () => clearTimeout(t);
  }, [dispatch, id, isNew]);

  useEffect(() => {
    const t = setTimeout(() => {
      if (!isNew && selected) {
        setForm({ ...selected });
        setPhotos(attachmentsToUploadItems(selected.attachments));
      } else if (isNew) {
        setForm(createEmptyIncidentDetection());
        setPhotos([]);
      }
    }, 0);
    return () => clearTimeout(t);
  }, [isNew, selected]);

  const patch = (p: Partial<IncidentDetection>) => {
    setForm((prev) => ({ ...prev, ...p }));
    setValidationErrors((prev) => clearFieldErrors(prev, Object.keys(p)));
  };

  const rules: ValidationRule<IncidentDetection>[] = [
    {
      field: 'detectedAt',
      sectionId: 'detection-section-info',
      validate: (f) => (!f.detectedAt ? L('timeRequired') : null),
    },
    {
      field: 'description',
      sectionId: 'detection-section-info',
      validate: (f) => (!f.description?.trim() ? L('descRequired') : null),
    },
    {
      field: 'targetDepartmentId',
      sectionId: 'detection-section-info',
      validate: (f) => (!f.targetDepartmentId ? L('deptRequired') : null),
    },
  ];

  const commitPhotos = async (entityId?: string): Promise<MedicalIncidentAttachment[]> => {
    const committed: MedicalIncidentAttachment[] = [];
    for (const item of photos) {
      const displayName = resolveUploadDisplayName(item);
      if (item.status === 'committed' && item.attachmentId) {
        committed.push({
          attachmentId: item.attachmentId,
          objectKey: item.objectKey || '',
          fileName: displayName,
          contentType: item.contentType,
          sizeBytes: item.sizeBytes,
          sortOrder: committed.length,
        });
        continue;
      }
      if (item.status !== 'staged' || !item.uploadId) continue;
      const saved = await filesEndpoint.commit({
        uploadId: item.uploadId,
        entityType: SCYK_DETECTION_ENTITY_TYPE,
        entityId,
      });
      committed.push({
        attachmentId: saved.attachmentId,
        objectKey: saved.objectKey,
        fileName: displayName || saved.fileName,
        contentType: saved.contentType,
        sizeBytes: saved.sizeBytes,
        sortOrder: committed.length,
      });
    }
    return committed;
  };

  const collectErrors = (requirePhoto: boolean): ValidationErrors => {
    const errors = runValidation(form, rules);
    if (photos.some((item) => item.status === 'uploading')) {
      errors.photos = L('uploadPending');
    } else if (photos.some((item) => item.status === 'error')) {
      errors.photos = scykDetectionImageUploadLabels.failed;
    } else if (requirePhoto && photos.filter((p) => p.status === 'staged' || p.status === 'committed').length < 1) {
      errors.photos = L('photoRequired');
    }
    return errors;
  };

  const persistDraft = async (): Promise<IncidentDetection | undefined> => {
    const errors = collectErrors(false);
    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      scrollToFirstErrorSection(errors, [
        ...rules,
        { field: 'photos', sectionId: 'field-section-photos', validate: () => null },
      ]);
      return undefined;
    }
    setValidationErrors({});
    const deptName = departmentOptions.find((d) => d.value === form.targetDepartmentId)?.label ?? form.targetDepartmentName ?? '';
    if (isNew) {
      const attachments = await commitPhotos();
      return dispatch(createIncidentDetection({
        ...form,
        targetDepartmentName: deptName,
        attachments,
      })).unwrap();
    }
    const attachments = await commitPhotos(id);
    return dispatch(updateIncidentDetection({
      id: id!,
      data: { ...form, targetDepartmentName: deptName, attachments },
    })).unwrap();
  };

  const handleSave = async () => {
    try {
      const saved = await persistDraft();
      if (!saved) return;
      dispatch(addToast({ message: L('saveDraft'), type: 'success' }));
      if (isNew) appNavigate(scykRoutes.detections.detail(saved.id), { replace: true });
    } catch (error: unknown) {
      dispatch(addToast({ message: getApiErrorMessage(error), type: 'error' }));
    }
  };

  const handleRoute = async () => {
    try {
      const errors = collectErrors(true);
      if (Object.keys(errors).length > 0) {
        setValidationErrors(errors);
        scrollToFirstErrorSection(errors, [
          ...rules,
          { field: 'photos', sectionId: 'field-section-photos', validate: () => null },
        ]);
        return;
      }
      const saved = await persistDraft();
      if (!saved) return;
      await dispatch(routeIncidentDetection(saved.id)).unwrap();
      dispatch(addToast({ message: L('route'), type: 'success' }));
      if (isNew) appNavigate(scykRoutes.detections.detail(saved.id), { replace: true });
    } catch (error: unknown) {
      dispatch(addToast({ message: getApiErrorMessage(error), type: 'error' }));
    }
  };

  const runAction = async (fn: () => Promise<unknown>, okKey: string) => {
    try {
      await fn();
      dispatch(addToast({ message: L(okKey), type: 'success' }));
    } catch (error: unknown) {
      dispatch(addToast({ message: getApiErrorMessage(error), type: 'error' }));
    }
  };

  const handleClaim = () => runAction(() => dispatch(claimIncidentDetection(id!)).unwrap(), 'claim');
  const handleCancel = () => runAction(() => dispatch(cancelIncidentDetection(id!)).unwrap(), 'cancel');

  const handleConvert = async () => {
    try {
      const incident = await dispatch(convertIncidentDetection(id!)).unwrap();
      dispatch(addToast({ message: L('convert'), type: 'success' }));
      appNavigate(scykRoutes.incidents.detail(incident.id));
    } catch (error: unknown) {
      dispatch(addToast({ message: getApiErrorMessage(error), type: 'error' }));
    }
  };

  const handleReject = async () => {
    if (!rejectReason.trim()) {
      setValidationErrors({ rejectReason: L('rejectReasonRequired') });
      return;
    }
    await runAction(
      () => dispatch(rejectIncidentDetection({ id: id!, reason: rejectReason.trim() })).unwrap(),
      'reject',
    );
    setRejectOpen(false);
    setRejectReason('');
  };

  const handleReassign = async () => {
    if (!reassignDeptId) {
      setValidationErrors({ targetDepartmentId: L('deptRequired') });
      return;
    }
    const name = departmentOptions.find((d) => d.value === reassignDeptId)?.label ?? '';
    await runAction(
      () => dispatch(reassignIncidentDetection({
        id: id!,
        targetDepartmentId: reassignDeptId,
        targetDepartmentName: name,
      })).unwrap(),
      'reassign',
    );
    setReassignOpen(false);
  };

  const handleBack = () => appNavigate(scykRoutes.detections.list);

  if (loading && !isNew) {
    return (
      <div className={styles.loadingWrap}>
        <i className="fas fa-spinner fa-spin" /> {L('loading')}
      </div>
    );
  }

  return (
    <div className={styles.page} data-testid="incident-detection-form">
      <div className={styles.stickyTop}>
        <div className={styles.pageHeader}>
          <div className={styles.titleGroup}>
            <button className={styles.backBtn} onClick={handleBack} aria-label={L('back')}>
              <i className="fas fa-arrow-left" />
            </button>
            <div>
              <h1 className={styles.title}>
                {isNew ? L('createTitle') : `${L('detailTitle')}: ${form.idCode || '...'}`}
              </h1>
              {!isNew && (
                <p className={styles.subtitle}>
                  <span className={styles.badge}>{statusLabel}</span>
                </p>
              )}
            </div>
          </div>
          <div className={styles.headerActions}>
            <Button variant="secondary" onClick={handleBack} disabled={saving}>{L('back')}</Button>
            {canEdit && (
              <Button variant="secondary" onClick={handleSave} disabled={saving}>
                {saving ? L('saving') : L('saveDraft')}
              </Button>
            )}
            {canEdit && (
              <Button variant="primary" onClick={handleRoute} disabled={saving}>{L('route')}</Button>
            )}
            {!isNew && status === IncidentDetectionStatus.Draft && isOwner && perms.canCancel && (
              <Button variant="danger" onClick={handleCancel} disabled={saving}>{L('cancel')}</Button>
            )}
            {canShowConvert && (
              <Button variant="primary" onClick={handleConvert} disabled={saving}>{L('convert')}</Button>
            )}
            {!isNew && status === IncidentDetectionStatus.Routed && canInboxAct && perms.canClaim && (
              <Button variant="primary" onClick={handleClaim} disabled={saving}>{L('claim')}</Button>
            )}
            {!isNew && (status === IncidentDetectionStatus.Routed || status === IncidentDetectionStatus.Claimed)
              && canInboxAct && perms.canReassign && (
              <Button variant="secondary" onClick={() => setReassignOpen(true)} disabled={saving}>{L('reassign')}</Button>
            )}
            {!isNew && (status === IncidentDetectionStatus.Routed || status === IncidentDetectionStatus.Claimed)
              && canInboxAct && perms.canReject && (
              <Button variant="danger" onClick={() => setRejectOpen(true)} disabled={saving}>{L('reject')}</Button>
            )}
            {!isNew && status === IncidentDetectionStatus.Converted && form.incidentId && (
              <Button variant="primary" onClick={() => appNavigate(scykRoutes.incidents.detail(form.incidentId!))}>
                {L('openIncident')}
              </Button>
            )}
          </div>
        </div>
        {Object.keys(validationErrors).length > 0 && (
          <div className={styles.errorBanner}>
            <i className="fas fa-exclamation-circle" />
            <div>
              <strong>{L('requiredBanner')}</strong>
              <ul className={styles.errorBannerList}>
                {Object.values(validationErrors).map((msg, i) => <li key={i}>{msg}</li>)}
              </ul>
            </div>
            <button className={styles.errorBannerClose} onClick={() => setValidationErrors({})} type="button">
              <i className="fas fa-times" />
            </button>
          </div>
        )}
      </div>

      <div className={styles.formBody}>
        <div className={styles.section} id="detection-section-info">
          <div className={styles.row}>
            <div className={styles.field}>
              <label>{L('idCode')}</label>
              <input type="text" value={form.idCode ?? ''} readOnly disabled />
            </div>
            <div className={`${styles.field} ${validationErrors.detectedAt ? styles.fieldHasError : ''}`}>
              <label>{L('detectedAt')} *</label>
              <input
                type="datetime-local"
                className={validationErrors.detectedAt ? styles.inputError : ''}
                value={utcToLocalInputValue(form.detectedAt)}
                onChange={(e) => patch({ detectedAt: localInputToISOWithOffset(e.target.value) })}
                disabled={!canEdit}
              />
              {validationErrors.detectedAt && <span className={styles.fieldError}>{validationErrors.detectedAt}</span>}
            </div>
          </div>

          <div className={`${styles.field} ${validationErrors.description ? styles.fieldHasError : ''}`}>
            <label>{L('description')} *</label>
            <textarea
              rows={4}
              className={validationErrors.description ? styles.inputError : ''}
              value={form.description ?? ''}
              onChange={(e) => patch({ description: e.target.value })}
              disabled={!canEdit}
            />
            {validationErrors.description && <span className={styles.fieldError}>{validationErrors.description}</span>}
          </div>

          <div className={`${styles.field} ${validationErrors.targetDepartmentId ? styles.fieldHasError : ''}`}>
            <label>{L('targetDepartment')} *</label>
            <Select
              label=""
              options={departmentOptions}
              value={form.targetDepartmentId ?? ''}
              onChange={(e) => patch({
                targetDepartmentId: e.target.value,
                targetDepartmentName: departmentOptions.find((d) => d.value === e.target.value)?.label ?? '',
              })}
              disabled={!canEdit}
              size="small"
            />
            {validationErrors.targetDepartmentId && (
              <span className={styles.fieldError}>{validationErrors.targetDepartmentId}</span>
            )}
          </div>

          <div className={styles.field}>
            <IncidentLocationSearchInput
              mode="specific_location"
              label={L('location')}
              value={form.locationText ?? ''}
              onChange={(v) => patch({ locationText: v })}
              disabled={!canEdit}
            />
          </div>
        </div>

        <div className={styles.section}>
          <DetectionPhotosSection
            entityId={isNew ? undefined : id}
            items={photos}
            onChange={(items) => {
              setPhotos(items as DetectionUploadItem[]);
              setValidationErrors((prev) => clearFieldErrors(prev, ['photos']));
            }}
            disabled={!canEdit}
            title={L('photos')}
          />
          {validationErrors.photos && <span className={styles.fieldError}>{validationErrors.photos}</span>}
        </div>

        {form.rejectReason && (
          <div className={styles.section}>
            <div className={styles.field}>
              <label>{L('rejectReason')}</label>
              <textarea rows={2} value={form.rejectReason} readOnly disabled />
            </div>
          </div>
        )}
      </div>

      {rejectOpen && (
        <div className={styles.overlay}>
          <div className={styles.dialog}>
            <h3>{L('reject')}</h3>
            <div className={styles.field}>
              <label>{L('rejectReason')} *</label>
              <textarea rows={3} value={rejectReason} onChange={(e) => setRejectReason(e.target.value)} />
            </div>
            <div className={styles.dialogActions}>
              <Button variant="secondary" onClick={() => setRejectOpen(false)}>{L('back')}</Button>
              <Button variant="danger" onClick={handleReject} disabled={saving}>{L('reject')}</Button>
            </div>
          </div>
        </div>
      )}

      {reassignOpen && (
        <div className={styles.overlay}>
          <div className={styles.dialog}>
            <h3>{L('reassign')}</h3>
            <Select
              label={L('targetDepartment')}
              options={departmentOptions}
              value={reassignDeptId}
              onChange={(e) => setReassignDeptId(e.target.value)}
              size="small"
            />
            <div className={styles.dialogActions}>
              <Button variant="secondary" onClick={() => setReassignOpen(false)}>{L('back')}</Button>
              <Button variant="primary" onClick={handleReassign} disabled={saving}>{L('reassign')}</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default IncidentDetectionFormPage;
